create extension if not exists "uuid-ossp";
create table if not exists subjects (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, name text not null, color text default '#4f46e5', icon text default 'book', created_at timestamptz default now());
create table if not exists recordings (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id) on delete cascade, subject_id uuid references subjects(id) on delete set null, title text, duration integer default 0, storage_path text, status text default 'recording' check (status in ('recording','uploading','processing','completed','failed')), created_at timestamptz default now(), completed_at timestamptz);
create table if not exists audio_chunks (id uuid primary key default uuid_generate_v4(), recording_id uuid references recordings(id) on delete cascade, chunk_index integer not null, storage_path text not null, duration integer, file_size bigint, uploaded_at timestamptz default now(), unique(recording_id, chunk_index));
create table if not exists transcripts (id uuid primary key default uuid_generate_v4(), recording_id uuid references recordings(id) on delete cascade, raw_text text, segments jsonb, summary jsonb, key_concepts jsonb, exam_alerts jsonb, quiz_questions jsonb, language text, processed_at timestamptz default now());
create table if not exists exam_alerts (id uuid primary key default uuid_generate_v4(), transcript_id uuid references transcripts(id) on delete cascade, keyword text not null, context text, importance text check (importance in ('high','medium','low')), timestamp text, start_time float, end_time float, created_at timestamptz default now());
alter table subjects enable row level security; alter table recordings enable row level security; alter table audio_chunks enable row level security; alter table transcripts enable row level security; alter table exam_alerts enable row level security;
create policy "own subjects" on subjects for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own recordings" on recordings for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy "own chunks" on audio_chunks for all using (exists(select 1 from recordings r where r.id=recording_id and r.user_id=auth.uid())) with check (exists(select 1 from recordings r where r.id=recording_id and r.user_id=auth.uid()));
create policy "own transcripts" on transcripts for all using (exists(select 1 from recordings r where r.id=recording_id and r.user_id=auth.uid())) with check (exists(select 1 from recordings r where r.id=recording_id and r.user_id=auth.uid()));
create policy "own alerts" on exam_alerts for all using (exists(select 1 from transcripts t join recordings r on r.id=t.recording_id where t.id=transcript_id and r.user_id=auth.uid())) with check (exists(select 1 from transcripts t join recordings r on r.id=t.recording_id where t.id=transcript_id and r.user_id=auth.uid()));
